=== FILE: tb/uart_tx_root_cause_repro.v ===
// Root-cause repro for uart_tx: a start pulse while a frame is in flight must
// be ignored (module header contract). The test sends 0xA5, pulses start with
// 0x5A during data bit 2, and checks that the full 0xA5 frame is still sent
// 8N1, LSB first, and that no second frame follows.
`timescale 1ns / 1ps
module uart_tx_root_cause_repro;
    localparam integer CLKS_PER_BIT  = 4;
    localparam [7:0]   FRAME_BYTE    = 8'hA5;
    localparam [7:0]   INTRUDER_BYTE = 8'h5A;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'h00;
    wire       tx;
    wire       busy;

    uart_tx #(.CLKS_PER_BIT(CLKS_PER_BIT)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    reg [8*128-1:0] nonce;
    integer passed;
    integer failed;
    integer n;
    integer b;
    integer k;
    reg     exp_bit;
    reg     idle_ok;

    task check;
        input            ok;
        input [8*64-1:0] what;
        begin
            if (ok)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK FAIL at %0t: %0s", $time, what);
            end
        end
    endtask

    initial begin
        passed = 0;
        failed = 0;
        nonce  = 0;
        if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
            if (!$value$plusargs("nirmaan_nonce=%s", nonce))
                if (!$value$plusargs("NONCE=%s", nonce))
                    if (!$value$plusargs("nonce=%s", nonce))
                        nonce = 0;

        // Synchronous reset, inputs driven on the falling edge.
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (3) @(negedge clk);
        check(tx === 1'b1 && busy === 1'b0, "idle after reset: tx high, busy low");

        // Launch one frame. The pulse is sampled at the next rising edge (P0).
        start = 1'b1;
        data  = FRAME_BYTE;
        @(negedge clk);              // N0, just after P0
        start = 1'b0;
        data  = 8'h00;

        // Bit b (0 = start, 1..8 = data LSB first, 9 = stop) is on tx from
        // P(4b) to P(4b+4). Sample it mid-bit, at negedge N(4b+2).
        for (n = 1; n <= 41; n = n + 1) begin
            @(negedge clk);
            if (n == 13) begin
                // Intruding start during data bit 2, sampled at P14.
                start = 1'b1;
                data  = INTRUDER_BYTE;
            end else begin
                start = 1'b0;
                data  = 8'h00;
            end
            if (n == 14)
                check(busy === 1'b1, "busy high when the intruding start arrives");
            if ((n % 4) == 2 && n <= 38) begin
                b = n / 4;
                if (b == 0)
                    exp_bit = 1'b0;
                else if (b == 9)
                    exp_bit = 1'b1;
                else
                    exp_bit = FRAME_BYTE[b-1];
                if (tx === exp_bit)
                    passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $display("CHECK FAIL at %0t: frame bit %0d expected %b got %b",
                             $time, b, exp_bit, tx);
                end
            end
        end

        // The ignored pulse must not launch a second frame.
        idle_ok = 1'b1;
        for (k = 0; k < 12 * CLKS_PER_BIT; k = k + 1) begin
            @(negedge clk);
            if (tx !== 1'b1 || busy !== 1'b0)
                idle_ok = 1'b0;
        end
        check(idle_ok, "line idle after the frame: no second frame");

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
